/* 
  Excellent RESTful Paginated Response 
*/

// GET /api/products?page=2&limit=20
{
  "data": [
    { "id": 21, "name": "Shoe 21" },
    // ... 19 more items
  ],
  // Metadata is CRITICAL so the frontend knows how to draw the pagination buttons!
  "meta": {
    "totalItems": 5000,
    "itemsPerPage": 20,
    "currentPage": 2,
    "totalPages": 250,
    "hasNextPage": true,
    "hasPrevPage": true
  }
}
